import math

N = 2345
a_solutions = []

# Find all factors of N
factors = []
for i in range(1, int(math.sqrt(N)) + 1):
    if N % i == 0:
        factors.append(i)
        if i * i != N:
            factors.append(N // i)

# Iterate over factor pairs (x1, x2) where x1 <= x2
factor_pairs = []
factors_sorted = sorted(factors)
for i in range(len(factors_sorted)):
    x1 = factors_sorted[i]
    x2 = N // x1
    if x1 <= x2:
        factor_pairs.append((x1, x2))

print(f"Factors of {N}: {sorted(factors)}")
print(f"Checking factor pairs (x1, x2):")

for x1, x2 in factor_pairs:
    # Check for positive factors first, as required by a >= 2

    # Check a1 from x1
    a1_num = x1 + 335
    a1_den = 328
    a1 = None
    if a1_num % a1_den == 0:
        a1_cand = a1_num // a1_den
        if a1_cand >= 2:
            a1 = a1_cand

    # Check a2 from x2
    a2_num = x2 + 335
    a2_den = 328
    a2 = None
    if a2_num % a2_den == 0:
        a2_cand = a2_num // a2_den
        if a2_cand >= 2:
            a2 = a2_cand

    if a1 is not None and a2 is not None:
        if a1 != a2:
            # Found a solution set {a1, a2}
            print(f"Solution found: x1={x1}, x2={x2} -> a1={a1}, a2={a2}")
            a_solutions.append(tuple(sorted((a1, a2))))
        else:
             # Note: if a1=a2, it's not a solution based on the problem stating distinct integers
             print(f"Solution found, but a1=a2: x1={x1}, x2={x2} -> a1={a1}, a2={a2}")
    elif a1 is not None and a2 is None:
        print(f"x1={x1} yields a1={a1}. x2={x2} does not yield integer a2 >= 2.")
    elif a1 is None and a2 is not None:
        print(f"x2={x2} yields a2={a2}. x1={x1} does not yield integer a1 >= 2.")
    else:
        print(f"No valid solutions for a1 or a2 for pair ({x1}, {x2}).")

print("\nTotal distinct solution sets found:", a_solutions)

